<script setup lang="ts">
import{computed,onMounted}from"vue";import SistemasToolbar from"@/components/engrase/catalogo/sistemas/SistemasToolbar.vue";import SistemasTable from"@/components/engrase/catalogo/sistemas/SistemasTable.vue";import SistemasMobileList from"@/components/engrase/catalogo/sistemas/SistemasMobileList.vue";import SistemasMobileFilterSheet from"@/components/engrase/catalogo/sistemas/SistemasMobileFilterSheet.vue";import SistemasListState from"@/components/engrase/catalogo/sistemas/SistemasListState.vue";import SistemaDetailDrawer from"@/components/engrase/catalogo/sistemas/SistemaDetailDrawer.vue";import SistemaUpdateConfirmDialog from"@/components/engrase/catalogo/sistemas/SistemaUpdateConfirmDialog.vue";import SistemaUnsavedDialog from"@/components/engrase/catalogo/sistemas/SistemaUnsavedDialog.vue";import{useCatalogoSistemas}from"@/composables/engrase/catalogo/useCatalogoSistemas";import{mensajeCatalogoSistemasError}from"@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.errors";import type{CatalogoSistemaItem}from"@/stores/dbequipos/engrase/catalogo/sistemasCatalogo.types";
const catalogo=useCatalogoSistemas();const listState=computed<"loading"|"error"|"empty"|"no-results"|null>(()=>catalogo.loadingInicial.value?"loading":catalogo.errorInicial.value?"error":catalogo.cargado.value&&!catalogo.items.value.length?"empty":catalogo.sinResultados.value?"no-results":null);const totalLabel=computed(()=>new Intl.NumberFormat("es").format(catalogo.items.value.length));const visibleLabel=computed(()=>new Intl.NumberFormat("es").format(catalogo.cantidadVisible.value));const saveError=computed(()=>mensajeCatalogoSistemasError(catalogo.errorGuardado.value));const filterCount=computed(()=>Number(catalogo.estado.value!=="activos")+Number(catalogo.uso.value!=="todos"));onMounted(()=>void catalogo.inicializar());function openItem(item:CatalogoSistemaItem,trigger:HTMLElement){catalogo.abrirEditar(item,trigger)}
</script>
<template><section class="flex min-h-0 min-w-0 flex-1 flex-col rounded-lg border border-gray-200 bg-[#FAF9F5] shadow-sm"><div class="min-w-0 flex-1 p-3 sm:p-4 lg:flex lg:min-h-0 lg:flex-col" :class="catalogo.drawerOpen.value?'lg:pr-[calc(clamp(340px,30vw,420px)+1rem)]':''"><SistemasToolbar :busqueda="catalogo.busqueda.value" :estado="catalogo.estado.value" :uso="catalogo.uso.value" :can-clear="catalogo.hayFiltrosActivos.value" :active-filter-count="filterCount" @update-busqueda="catalogo.actualizarBusqueda" @update-estado="catalogo.actualizarEstado" @update-uso="catalogo.actualizarUso" @open-filters="catalogo.filtrosMobileAbiertos.value=true" @clear="catalogo.limpiarFiltros" @create="catalogo.abrirCrear"/><header class="mt-4 border-t pt-3"><h2 data-catalogo-sistemas-heading tabindex="-1" class="text-sm font-bold text-main">Sistemas</h2><p class="text-xs text-gray-500" aria-live="polite">{{ visibleLabel }} resultados</p></header><div class="mt-3 lg:min-h-0 lg:flex-1 lg:overflow-y-auto"><SistemasListState v-if="listState" :kind="listState" :message="mensajeCatalogoSistemasError(catalogo.errorInicial.value)" @retry="catalogo.reintentar" @clear="catalogo.limpiarFiltros" @create="catalogo.abrirCrear"/><template v-else><SistemasTable :items="catalogo.itemsVisibles.value" :selected-id="catalogo.seleccionadoId.value" :sort-key="catalogo.sortKey.value" :sort-direction="catalogo.sortDirection.value" @select="openItem" @sort="catalogo.actualizarOrden"/><SistemasMobileList :items="catalogo.itemsVisibles.value" :selected-id="catalogo.seleccionadoId.value" @select="openItem"/><p class="mt-3 text-xs tabular-nums text-gray-500">Mostrando {{ visibleLabel }} de {{ totalLabel }} sistemas</p></template></div></div><SistemasMobileFilterSheet v-if="catalogo.filtrosMobileAbiertos.value" :open="catalogo.filtrosMobileAbiertos.value" :estado="catalogo.estado.value" :uso="catalogo.uso.value" :result-count="catalogo.cantidadVisible.value" @close="catalogo.filtrosMobileAbiertos.value=false" @reset="catalogo.limpiarFiltros" @update-estado="catalogo.actualizarEstado" @update-uso="catalogo.actualizarUso"/><SistemaDetailDrawer :open="catalogo.drawerOpen.value" :mode="catalogo.modo.value" :item="catalogo.original.value" :draft="catalogo.draft.value" :has-changes="catalogo.hasChanges.value" :can-submit="catalogo.canSubmit.value" :saving="catalogo.guardando.value" :field-errors="catalogo.fieldErrors.value" :save-error="saveError" @update-draft="catalogo.updateDraft" @blur-name="catalogo.validateName" @request-close="catalogo.solicitarCierre" @cancel="catalogo.solicitarCierre" @submit="catalogo.submit"/><SistemaUpdateConfirmDialog v-if="catalogo.confirmacionAbierta.value&&catalogo.original.value&&catalogo.draft.value" :original="catalogo.original.value" :draft="catalogo.draft.value" :saving="catalogo.guardando.value" @cancel="catalogo.cancelarConfirmacion" @confirm="catalogo.confirmarActualizacion"/><SistemaUnsavedDialog v-if="catalogo.confirmarDescarteAbierto.value" @cancel="catalogo.cancelarDescarte" @discard="catalogo.cerrarAhora"/><div class="pointer-events-none fixed right-4 top-4 z-[90]" aria-live="polite"><p v-if="catalogo.successMessage.value" class="rounded-md border border-success/25 bg-white px-4 py-3 text-sm font-semibold text-success shadow-lg">{{ catalogo.successMessage.value }}</p></div></section></template>
